package app.manga.manga;
import jakarta.validation.constraints.*;import java.util.Map;import java.util.List;import org.springframework.validation.annotation.Validated;import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/v1") @Validated public class MangaController {private final JikanProvider j;public MangaController(JikanProvider j){this.j=j;}
 @GetMapping("/manga") public Object catalog(@RequestParam(required=false)@Size(max=100)String q,@RequestParam(required=false)String genre,@RequestParam(required=false)String status,@RequestParam(required=false)String type,@RequestParam(defaultValue="popularity")String orderBy,@RequestParam(defaultValue="desc")String sort,@RequestParam(defaultValue="1")@Min(1)int page,@RequestParam(defaultValue="24")@Min(1)@Max(25)int limit){String order=Map.of("popularity","popularity","score","score","title","title").get(orderBy);if(order==null)throw new IllegalArgumentException("Pengurutan tidak didukung.");if(!List.of("asc","desc").contains(sort))throw new IllegalArgumentException("Arah pengurutan tidak valid.");if(status!=null&&!List.of("publishing","complete","hiatus","discontinued","upcoming").contains(status))throw new IllegalArgumentException("Status manga tidak didukung.");if(type!=null&&!List.of("manga","novel","lightnovel","oneshot","doujin","manhwa","manhua").contains(type))throw new IllegalArgumentException("Tipe manga tidak didukung.");if(genre!=null&&!genre.matches("\\d{1,4}"))throw new IllegalArgumentException("Genre tidak valid.");var result=j.catalog(q,genre,status,type,order,sort,page,limit);return Map.of("data",result.data(),"pagination",result.pagination());}
 @GetMapping("/manga/top")public Object top(@RequestParam(defaultValue="1")@Min(1)int page,@RequestParam(defaultValue="24")@Min(1)@Max(25)int limit){var x=j.top(page,limit);return Map.of("data",x.data(),"pagination",x.pagination());}
 @GetMapping("/manga/{id}")public Object detail(@PathVariable@Min(1)long id){return Map.of("data",j.detail(id));}
 @GetMapping("/genres")public Object genres(){return Map.of("data",j.genres());}
}
